  "check_code": """"Deterministic checks for the Endur registry lifecycle correction."""

import hashlib
import json
import sqlite3
from pathlib import Path


SYSTEM = "endur_eua_position_ledger"
TARGET_TRADE = "EUA-2025-0126"
TARGET_LEG = "EUAL-2025-0126-01"
TARGET_MOVEMENT = "URM-2025-00523"
BASELINE_MOVEMENT_COUNT = 185
BASELINE_MOVEMENT_HASH = "90324c29e0e2b7ba58ac313fe303e4eadeaec936e903b557ed9b44d5aa8519ef"


def _paths(ws):
    root = Path(ws).resolve().parent
    system_dir = root / "system" / SYSTEM
    return system_dir / "state.db", system_dir / "state.db.pinned_backup"


def _connect(path):
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    return connection


def _rows(connection, query, params=()):
    return [dict(row) for row in connection.execute(query, params).fetchall()]


def _qualifying_reversals(connection):
    return _rows(
        connection,
        """SELECT * FROM registry_movements
           WHERE reversal_movement_id=?
             AND registry_account_id='EU-100-5012378-0-17'
             AND trade_id='EUA-2025-0126'
             AND movement_type='TRANSFER_OUT'
             AND movement_date='2025-09-12'
             AND quantity_milli_eua=1000000
             AND movement_status='COMPLETED'""",
        (TARGET_MOVEMENT,),
    )


def check_completed_offsetting_reversal(ws):
    state_path, backup_path = _paths(ws)
    try:
        with _connect(state_path) as current, _connect(backup_path) as baseline:
            qualifying = _qualifying_reversals(current)
            baseline_ids = {
                row["movement_id"]
                for row in _rows(baseline, "SELECT movement_id FROM registry_movements")
            }
            all_links = _rows(
                current,
                "SELECT movement_id FROM registry_movements WHERE reversal_movement_id=?",
                (TARGET_MOVEMENT,),
            )
    except Exception as exc:
        return {"score": 0, "detail": f"Unable to inspect Endur movement state: {exc}"}

    if len(qualifying) != 1:
        return {
            "score": 0,
            "detail": f"Expected one qualifying completed outbound reversal; found {len(qualifying)}.",
        }
    movement_id = qualifying[0]["movement_id"]
    if movement_id in baseline_ids:
        return {"score": 0, "detail": "The qualifying row was not newly added by this task."}
    if len(all_links) != 1:
        return {
            "score": 0,
            "detail": f"Expected exactly one movement linked as the reversal; found {len(all_links)}.",
        }
    return {"score": 1, "detail": f"Found qualifying reversal movement {movement_id}."}


def check_idempotent_control_record(ws):
    state_path, _ = _paths(ws)
    try:
        with _connect(state_path) as current:
            if not current.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name='_movement_idempotency'"
            ).fetchone():
                return {"score": 0, "detail": "No movement idempotency table was created."}
            qualifying = _qualifying_reversals(current)
            if len(qualifying) != 1:
                return {"score": 0, "detail": "A unique qualifying reversal is required first."}
            movement = qualifying[0]
            records = _rows(
                current,
                "SELECT * FROM _movement_idempotency WHERE movement_id=?",
                (movement["movement_id"],),
            )
    except Exception as exc:
        return {"score": 0, "detail": f"Unable to inspect idempotency state: {exc}"}

    if len(records) != 1:
        return {
            "score": 0,
            "detail": f"Expected one idempotency record for the reversal; found {len(records)}.",
        }
    record = records[0]
    fields = (
        "registry_account_id",
        "movement_type",
        "movement_date",
        "quantity_milli_eua",
        "movement_status",
        "trade_id",
        "registry_reference",
        "reversal_movement_id",
        "note",
    )
    mismatches = [field for field in fields if record[field] != movement[field]]
    if mismatches:
        return {
            "score": 0,
            "detail": "Idempotency payload differs from the movement on: " + ", ".join(mismatches),
        }
    return {"score": 1, "detail": "The persisted idempotency payload matches the reversal movement."}


def check_target_source_rows_unchanged(ws):
    state_path, backup_path = _paths(ws)
    targets = (
        ("commodity_trades", "trade_id", TARGET_TRADE),
        ("eua_trade_legs", "trade_leg_id", TARGET_LEG),
        ("registry_movements", "movement_id", TARGET_MOVEMENT),
    )
    try:
        with _connect(state_path) as current, _connect(backup_path) as baseline:
            for table, key, value in targets:
                current_rows = _rows(current, f"SELECT * FROM {table} WHERE {key}=?", (value,))
                baseline_rows = _rows(baseline, f"SELECT * FROM {table} WHERE {key}=?", (value,))
                if current_rows != baseline_rows:
                    return {"score": 0, "detail": f"Protected source row changed: {table}.{key}={value}."}
    except Exception as exc:
        return {"score": 0, "detail": f"Unable to compare protected source rows: {exc}"}
    return {"score": 1, "detail": "The canceled trade, canceled leg, and original receipt are unchanged."}


def check_unrelated_movements_unchanged(ws):
    state_path, _ = _paths(ws)
    try:
        with _connect(state_path) as current:
            qualifying = _qualifying_reversals(current)
            current_count = current.execute("SELECT COUNT(*) FROM registry_movements").fetchone()[0]
            if len(qualifying) > 1:
                return {
                    "score": 0,
                    "detail": f"More than one qualifying reversal exists: {len(qualifying)}.",
                }
            if qualifying:
                movement_id = qualifying[0]["movement_id"]
                retained_rows = _rows(
                    current,
                    "SELECT * FROM registry_movements WHERE movement_id<>? ORDER BY movement_id",
                    (movement_id,),
                )
            else:
                retained_rows = _rows(current, "SELECT * FROM registry_movements ORDER BY movement_id")
    except Exception as exc:
        return {"score": 0, "detail": f"Unable to compare registry movement history: {exc}"}

    retained_hash = hashlib.sha256(
        json.dumps(
            retained_rows,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
    ).hexdigest()
    if len(retained_rows) != BASELINE_MOVEMENT_COUNT or retained_hash != BASELINE_MOVEMENT_HASH:
        return {"score": 0, "detail": "A pre-existing registry movement was changed/deleted or an unrelated movement was added."}
    expected_count = BASELINE_MOVEMENT_COUNT + len(qualifying)
    if current_count != expected_count:
        return {
            "score": 0,
            "detail": f"Unexpected movement count; expected={expected_count}, current={current_count}.",
        }
    detail = "All pinned movements are unchanged."
    if qualifying:
        detail += " The only added movement is the qualifying reversal."
    return {"score": 1, "detail": detail}
